const comments = {
  comment: {
    pattern: /\/\/[\s\S]*$/,
    greedy: true,
  },
  commentMultiline: {
    pattern: /\/\*[\s\S]*?\*\//m,
    alias: 'comment',
    greedy: true,
  },
};

const commandNamePattern = /[A-Za-z]+/;
const commandParametersPattern = new RegExp(
  `(${commandNamePattern.source})[^|]*`,
);

const commandName = {
  commandName: {
    pattern: commandNamePattern,
    alias: 'keyword',
  },
};

export const prismDqlLanguage = {
  ...comments,
  command: {
    pattern: new RegExp(`${commandParametersPattern.source}\\|?`, 'm'),
    greedy: true,
    inside: {
      commandParameters: {
        pattern: commandParametersPattern,
        lookbehind: true,
        inside: {
          string: {
            pattern: /"[\s\S]*?"/m,
          },
          backtickstring: {
            pattern: /`[\s\S]*?`/m,
            alias: 'string',
          },
          number: /(\d+(?:\.\d+)?)(?![.\w])/,
          parameterName: { pattern: /\w+:/, alias: 'variable' },
          ...comments,
          commandName: {
            pattern: new RegExp(`(\\[\\s*)${commandNamePattern.source}`),
            lookbehind: true,
            alias: 'keyword',
          },
        },
        ...commandName,
      },
      ...commandName,
    },
  },
};
